'use client';

import { useState, useEffect } from 'react';
import Icon from '@/components/ui/AppIcon';

interface Recommendation {
  id: number;
  name: string;
  role: string;
  company: string;
  image: string;
  imageAlt: string;
  recommendation: string;
  relationship: string;
}

interface PeerRecommendationsProps {
  recommendations: Recommendation[];
}

const PeerRecommendations = ({ recommendations }: PeerRecommendationsProps) => {
  const [isHydrated, setIsHydrated] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    setIsHydrated(true);
  }, []);

  if (!isHydrated) {
    return (
      <div data-component-id="app\experience\components\PeerRecommendations.tsx:31:6" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="31" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22bg-card%20border%20border-subtle%20rounded-xl%20p-6%22%7D" className="bg-card border border-subtle rounded-xl p-6">
        <div data-component-id="app\experience\components\PeerRecommendations.tsx:32:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="32" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22h-6%20bg-muted%20rounded%20w-1%2F3%20animate-pulse%20mb-4%22%7D" className="h-6 bg-muted rounded w-1/3 animate-pulse mb-4"></div>
        <div data-component-id="app\experience\components\PeerRecommendations.tsx:33:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="33" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22h-40%20bg-muted%20rounded%20animate-pulse%22%7D" className="h-40 bg-muted rounded animate-pulse"></div>
      </div>
    );
  }

  const nextRecommendation = () => {
    setCurrentIndex((prev) => (prev + 1) % recommendations.length);
  };

  const prevRecommendation = () => {
    setCurrentIndex((prev) => (prev - 1 + recommendations.length) % recommendations.length);
  };

  const renderRecommendation = (rec: Recommendation) => (
    <div data-component-id="app\experience\components\PeerRecommendations.tsx:47:4" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="47" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20items-start%20gap-4%20mb-6%20last%3Amb-0%22%7D" className="flex items-start gap-4 mb-6 last:mb-0">
      <div data-component-id="app\experience\components\PeerRecommendations.tsx:48:6" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="48" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22w-16%20h-16%20rounded-full%20overflow-hidden%20flex-shrink-0%20border-2%20border-brand-cyan%22%7D" className="w-16 h-16 rounded-full overflow-hidden flex-shrink-0 border-2 border-brand-cyan">
        <img data-component-id="app\experience\components\PeerRecommendations.tsx:49:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="49" data-component-file="PeerRecommendations.tsx" data-component-name="img" data-component-content="%7B%22elementName%22%3A%22img%22%2C%22className%22%3A%22w-full%20h-full%20object-cover%22%7D" src={rec.image} alt={rec.imageAlt} className="w-full h-full object-cover" />
      </div>
      <div data-component-id="app\experience\components\PeerRecommendations.tsx:51:6" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="51" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex-1%22%7D" className="flex-1">
        <h4 data-component-id="app\experience\components\PeerRecommendations.tsx:52:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="52" data-component-file="PeerRecommendations.tsx" data-component-name="h4" data-component-content="%7B%22elementName%22%3A%22h4%22%2C%22className%22%3A%22text-lg%20font-semibold%20text-text-primary%22%7D" className="text-lg font-semibold text-text-primary">{rec.name}</h4>
        <p data-component-id="app\experience\components\PeerRecommendations.tsx:53:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="53" data-component-file="PeerRecommendations.tsx" data-component-name="p" data-component-content="%7B%22elementName%22%3A%22p%22%2C%22className%22%3A%22text-sm%20text-brand-cyan%22%7D" className="text-sm text-brand-cyan">{rec.role}</p>
        <p data-component-id="app\experience\components\PeerRecommendations.tsx:54:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="54" data-component-file="PeerRecommendations.tsx" data-component-name="p" data-component-content="%7B%22elementName%22%3A%22p%22%2C%22className%22%3A%22text-xs%20text-text-secondary%22%7D" className="text-xs text-text-secondary">{rec.company}</p>
        <span data-component-id="app\experience\components\PeerRecommendations.tsx:55:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="55" data-component-file="PeerRecommendations.tsx" data-component-name="span" data-component-content="%7B%22elementName%22%3A%22span%22%2C%22className%22%3A%22inline-block%20mt-1%20px-2%20py-1%20bg-brand-purple%2F20%20text-brand-purple%20text-xs%20rounded-full%22%7D" className="inline-block mt-1 px-2 py-1 bg-brand-purple/20 text-brand-purple text-xs rounded-full">
          {rec.relationship}
        </span>
        <div data-component-id="app\experience\components\PeerRecommendations.tsx:58:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="58" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22relative%20mt-3%22%7D" className="relative mt-3">
          <p data-component-id="app\experience\components\PeerRecommendations.tsx:59:10" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="59" data-component-file="PeerRecommendations.tsx" data-component-name="p" data-component-content="%7B%22elementName%22%3A%22p%22%2C%22className%22%3A%22text-text-secondary%20leading-relaxed%20pl-5%20italic%22%2C%22textContent%22%3A%22%5C%22%20%5C%22%22%7D" className="text-text-secondary leading-relaxed pl-5 italic">
            "{rec.recommendation}"
          </p>
        </div>
      </div>
    </div>
  );

  return (
    <div data-component-id="app\experience\components\PeerRecommendations.tsx:68:4" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="68" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22bg-card%20border%20border-subtle%20rounded-xl%20p-6%22%7D" className="bg-card border border-subtle rounded-xl p-6">
      <div data-component-id="app\experience\components\PeerRecommendations.tsx:69:6" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="69" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20items-center%20gap-2%20mb-6%22%7D" className="flex items-center gap-2 mb-6">
        <Icon data-component-id="app\experience\components\PeerRecommendations.tsx:70:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="70" data-component-file="PeerRecommendations.tsx" data-component-name="Icon" data-component-content="%7B%22elementName%22%3A%22Icon%22%2C%22name%22%3A%22ChatBubbleLeftRightIcon%22%2C%22className%22%3A%22text-brand-green%22%7D" name="ChatBubbleLeftRightIcon" size={24} className="text-brand-green" />
        <h3 data-component-id="app\experience\components\PeerRecommendations.tsx:71:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="71" data-component-file="PeerRecommendations.tsx" data-component-name="h3" data-component-content="%7B%22elementName%22%3A%22h3%22%2C%22className%22%3A%22text-xl%20font-semibold%20text-text-primary%22%2C%22textContent%22%3A%22Peer%20Recommendations%22%7D" className="text-xl font-semibold text-text-primary">Peer Recommendations</h3>
      </div>

      {/* Desktop: Show both recommendations vertically */}
      <div data-component-id="app\experience\components\PeerRecommendations.tsx:75:6" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="75" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22hidden%20md%3Ablock%22%7D" className="hidden md:block">
        {recommendations.map((rec) => (
          <div data-component-id="app\experience\components\PeerRecommendations.tsx:77:10" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="77" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%7D" key={rec.id}>
            {renderRecommendation(rec)}
          </div>
        ))}
      </div>

      {/* Mobile: Show carousel */}
      <div data-component-id="app\experience\components\PeerRecommendations.tsx:84:6" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="84" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22md%3Ahidden%22%7D" className="md:hidden">
        <div data-component-id="app\experience\components\PeerRecommendations.tsx:85:8" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="85" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22relative%22%7D" className="relative">
          {renderRecommendation(recommendations[currentIndex])}
          
          <div data-component-id="app\experience\components\PeerRecommendations.tsx:88:10" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="88" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20items-center%20justify-between%22%7D" className="flex items-center justify-between">
            <div data-component-id="app\experience\components\PeerRecommendations.tsx:89:12" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="89" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20gap-1%22%7D" className="flex gap-1">
              {recommendations.map((_, idx) => (
                <button data-component-id="app\experience\components\PeerRecommendations.tsx:91:16" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="91" data-component-file="PeerRecommendations.tsx" data-component-name="button" data-component-content="%7B%22elementName%22%3A%22button%22%7D"
                  key={idx}
                  onClick={() => setCurrentIndex(idx)}
                  className={`w-2 h-2 rounded-full transition-all duration-250 ${
                    idx === currentIndex ? 'bg-brand-cyan w-6' : 'bg-muted'
                  }`}
                  aria-label={`Go to recommendation ${idx + 1}`}
                ></button>
              ))}
            </div>

            <div data-component-id="app\experience\components\PeerRecommendations.tsx:102:12" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="102" data-component-file="PeerRecommendations.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20gap-2%22%7D" className="flex gap-2">
              <button data-component-id="app\experience\components\PeerRecommendations.tsx:103:14" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="103" data-component-file="PeerRecommendations.tsx" data-component-name="button" data-component-content="%7B%22elementName%22%3A%22button%22%2C%22className%22%3A%22p-2%20bg-muted%20hover%3Abg-brand-cyan%2F20%20rounded-lg%20transition-colors%20duration-250%22%7D"
                onClick={prevRecommendation}
                className="p-2 bg-muted hover:bg-brand-cyan/20 rounded-lg transition-colors duration-250"
                aria-label="Previous recommendation"
              >
                <Icon data-component-id="app\experience\components\PeerRecommendations.tsx:108:16" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="108" data-component-file="PeerRecommendations.tsx" data-component-name="Icon" data-component-content="%7B%22elementName%22%3A%22Icon%22%2C%22name%22%3A%22ChevronLeftIcon%22%2C%22className%22%3A%22text-text-secondary%22%7D" name="ChevronLeftIcon" size={20} className="text-text-secondary" />
              </button>
              <button data-component-id="app\experience\components\PeerRecommendations.tsx:110:14" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="110" data-component-file="PeerRecommendations.tsx" data-component-name="button" data-component-content="%7B%22elementName%22%3A%22button%22%2C%22className%22%3A%22p-2%20bg-muted%20hover%3Abg-brand-cyan%2F20%20rounded-lg%20transition-colors%20duration-250%22%7D"
                onClick={nextRecommendation}
                className="p-2 bg-muted hover:bg-brand-cyan/20 rounded-lg transition-colors duration-250"
                aria-label="Next recommendation"
              >
                <Icon data-component-id="app\experience\components\PeerRecommendations.tsx:115:16" data-component-path="app\experience\components\PeerRecommendations.tsx" data-component-line="115" data-component-file="PeerRecommendations.tsx" data-component-name="Icon" data-component-content="%7B%22elementName%22%3A%22Icon%22%2C%22name%22%3A%22ChevronRightIcon%22%2C%22className%22%3A%22text-text-secondary%22%7D" name="ChevronRightIcon" size={20} className="text-text-secondary" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PeerRecommendations;