'use client';

import React, { useState, useEffect } from 'react';
import Image from 'next/image';

interface AppImageProps {
    src: string;
    alt: string;
    width?: number;
    height?: number;
    className?: string;
    priority?: boolean;
    quality?: number;
    placeholder?: 'blur' | 'empty';
    blurDataURL?: string;
    fill?: boolean;
    sizes?: string;
    onClick?: () => void;
    [key: string]: any;
}

function AppImage({
    src,
    alt,
    width,
    height,
    className = '',
    priority = false,
    quality = 75,
    placeholder = 'empty',
    blurDataURL,
    fill = false,
    sizes,
    onClick,
    ...props
}: AppImageProps) {
    const [imageSrc, setImageSrc] = useState(src || '');
    const [isLoading, setIsLoading] = useState(src ? true : false);
    const [hasError, setHasError] = useState(!src);

    // Sync state if src changes
    useEffect(() => {
        setImageSrc(src || '');
        setIsLoading(src ? true : false);
        setHasError(!src);
    }, [src]);

    // More reliable external URL detection
    const isExternal = typeof imageSrc === 'string' && (imageSrc.startsWith('http://') || imageSrc.startsWith('https://'));
    const isLocal = typeof imageSrc === 'string' && (imageSrc.startsWith('/') || imageSrc.startsWith('./') || imageSrc.startsWith('data:'));

    const handleError = () => {
        setIsLoading(false);
        setHasError(true);
    };

    const handleLoad = () => {
        setIsLoading(false);
        setHasError(false);
    };

    const commonClassName = `${className} ${isLoading ? 'animate-pulse bg-slate-800' : ''} ${onClick ? 'cursor-pointer hover:opacity-90 transition-opacity' : ''}`;

    if (hasError || !imageSrc) {
        return (
            <div data-component-id="src\components\ui\AppImage.tsx:66:12" data-component-path="src\components\ui\AppImage.tsx" data-component-line="66" data-component-file="AppImage.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22%5Bspread%5D%22%3A%22true%22%7D" 
                className={`flex flex-col items-center justify-center bg-gradient-to-br from-slate-900 to-slate-950 border border-slate-800 text-slate-400 select-none text-center p-6 rounded-xl ${fill ? 'absolute inset-0 w-full h-full' : ''} ${className}`}
                style={!fill ? { width: width || '100%', height: height || 240 } : {}}
                onClick={onClick}
                {...props}
            >
                <div data-component-id="src\components\ui\AppImage.tsx:72:16" data-component-path="src\components\ui\AppImage.tsx" data-component-line="72" data-component-file="AppImage.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20items-center%20justify-center%20w-12%20h-12%20rounded-lg%20bg-slate-800%2F80%20border%20border-slate-700%2F50%20text-indigo-400%20mb-3%20shadow-lg%20shadow-indigo-500%2F10%22%7D" className="flex items-center justify-center w-12 h-12 rounded-lg bg-slate-800/80 border border-slate-700/50 text-indigo-400 mb-3 shadow-lg shadow-indigo-500/10">
                    <svg data-component-id="src\components\ui\AppImage.tsx:73:20" data-component-path="src\components\ui\AppImage.tsx" data-component-line="73" data-component-file="AppImage.tsx" data-component-name="svg" data-component-content="%7B%22elementName%22%3A%22svg%22%2C%22className%22%3A%22w-6%20h-6%22%7D" className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                        <path data-component-id="src\components\ui\AppImage.tsx:74:24" data-component-path="src\components\ui\AppImage.tsx" data-component-line="74" data-component-file="AppImage.tsx" data-component-name="path" data-component-content="%7B%22elementName%22%3A%22path%22%7D" strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 9l3 3-3 3m5 0h3M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                </div>
                <span data-component-id="src\components\ui\AppImage.tsx:77:16" data-component-path="src\components\ui\AppImage.tsx" data-component-line="77" data-component-file="AppImage.tsx" data-component-name="span" data-component-content="%7B%22elementName%22%3A%22span%22%2C%22className%22%3A%22text-%5B10px%5D%20font-semibold%20tracking-wider%20text-slate-500%20uppercase%22%2C%22textContent%22%3A%22SYSTEM%20ARCHITECTURE%22%7D" className="text-[10px] font-semibold tracking-wider text-slate-500 uppercase">SYSTEM ARCHITECTURE</span>
                <span data-component-id="src\components\ui\AppImage.tsx:78:16" data-component-path="src\components\ui\AppImage.tsx" data-component-line="78" data-component-file="AppImage.tsx" data-component-name="span" data-component-content="%7B%22elementName%22%3A%22span%22%2C%22className%22%3A%22text-xs%20text-slate-400%20font-medium%20max-w-%5B85%25%5D%20truncate%20mt-1.5%22%7D" className="text-xs text-slate-400 font-medium max-w-[85%] truncate mt-1.5">{alt || 'Production System Card'}</span>
            </div>
        );
    }

    // For external URLs or when in doubt, use regular img tag
    if (isExternal && !isLocal) {
        const imgStyle: React.CSSProperties = {};

        if (width) imgStyle.width = width;
        if (height) imgStyle.height = height;

        if (fill) {
            return (
                <div data-component-id="src\components\ui\AppImage.tsx:92:16" data-component-path="src\components\ui\AppImage.tsx" data-component-line="92" data-component-file="AppImage.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%7D" className={`relative ${className}`} style={{ width: width || '100%', height: height || '100%' }}>
                    <img data-component-id="src\components\ui\AppImage.tsx:93:20" data-component-path="src\components\ui\AppImage.tsx" data-component-line="93" data-component-file="AppImage.tsx" data-component-name="img" data-component-content="%7B%22elementName%22%3A%22img%22%2C%22src%22%3A%22%5Bvar%3AimageSrc%5D%22%2C%22alt%22%3A%22%5Bvar%3Aalt%5D%22%2C%22%5Bspread%5D%22%3A%22true%22%7D"
                        src={imageSrc}
                        alt={alt}
                        className={`${commonClassName} absolute inset-0 w-full h-full object-cover`}
                        onError={handleError}
                        onLoad={handleLoad}
                        onClick={onClick}
                        style={imgStyle}
                        {...props}
                    />
                </div>
            );
        }

        return (
            <img data-component-id="src\components\ui\AppImage.tsx:108:12" data-component-path="src\components\ui\AppImage.tsx" data-component-line="108" data-component-file="AppImage.tsx" data-component-name="img" data-component-content="%7B%22elementName%22%3A%22img%22%2C%22src%22%3A%22%5Bvar%3AimageSrc%5D%22%2C%22alt%22%3A%22%5Bvar%3Aalt%5D%22%2C%22className%22%3A%22%5Bvar%3AcommonClassName%5D%22%2C%22%5Bspread%5D%22%3A%22true%22%7D"
                src={imageSrc}
                alt={alt}
                className={commonClassName}
                onError={handleError}
                onLoad={handleLoad}
                onClick={onClick}
                style={imgStyle}
                {...props}
            />
        );
    }

    // For local images and data URLs, use Next.js Image component
    const imageProps = {
        src: imageSrc,
        alt,
        className: commonClassName,
        priority,
        quality,
        placeholder,
        blurDataURL,
        unoptimized: true,
        onError: handleError,
        onLoad: handleLoad,
        onClick,
        ...props,
    };

    if (fill) {
        return (
            <div data-component-id="src\components\ui\AppImage.tsx:139:12" data-component-path="src\components\ui\AppImage.tsx" data-component-line="139" data-component-file="AppImage.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%7D" className={`relative ${className}`}>
                <Image data-component-id="src\components\ui\AppImage.tsx:140:16" data-component-path="src\components\ui\AppImage.tsx" data-component-line="140" data-component-file="AppImage.tsx" data-component-name="Image" data-component-content="%7B%22elementName%22%3A%22Image%22%2C%22%5Bspread%5D%22%3A%22true%22%7D"
                    {...imageProps}
                    fill
                    sizes={sizes || '100vw'}
                    style={{ objectFit: 'cover' }}
                />
            </div>
        );
    }

    return (
        <Image data-component-id="src\components\ui\AppImage.tsx:151:8" data-component-path="src\components\ui\AppImage.tsx" data-component-line="151" data-component-file="AppImage.tsx" data-component-name="Image" data-component-content="%7B%22elementName%22%3A%22Image%22%2C%22%5Bspread%5D%22%3A%22true%22%7D"
            {...imageProps}
            width={width || 400}
            height={height || 300}
        />
    );
}

export default AppImage;